    let s22: u128 = s15.wrapping_add(s21) & 0xffff;
    let v23 = b.konst(Width::new(16), s22);
    st.set(b, regs::WZ, v23, Some(v20));
    st.branch(b, Target::Const((s22) as u16), Kind::Jump, Some(v20));
    st.cycles(b, 13, Some(v20));
    let v24 = b.not(v20);
    st.cycles(b, 8, Some(v24));
