    st.set(b, regs::R, v12, None);
    let v14 = st.get(b, regs::H);
    let v15 = st.get(b, regs::L);
    let v16 = b.concat(v14, v15);
    let v17 = st.get(b, regs::D);
    let v18 = st.get(b, regs::E);
    let v19 = b.concat(v17, v18);
    let v20 = b.konst(Width::new(16), 0x1);
    let v21 = b.bin(BinOp::Add, v16, v20);
