    let v27 = b.extract(v25, 0, Width::new(8));
    st.set(b, regs::L, v27, None);
    let v28 = b.konst(Width::new(1), 0x1);
    st.set(b, regs::Q, v28, None);
    let v29 = b.extract(v24, 16, Width::new(1));
    st.set(b, regs::FC, v29, None);
    let v30 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FN, v30, None);
    let v31 = b.bin(BinOp::Xor, v16, v19);
    let v32 = b.bin(BinOp::Xor, v31, v25);
    let v33 = b.extract(v32, 12, Width::new(1));
    st.set(b, regs::FH, v33, None);
    let v34 = b.extract(v25, 13, Width::new(1));
    st.set(b, regs::FY, v34, None);
    let v35 = b.extract(v25, 11, Width::new(1));
    st.set(b, regs::FX, v35, None);
