    st.set(b, regs::FH, v34, None);
    let v35 = b.extract(v19, 7, Width::new(1));
    st.set(b, regs::FS, v35, None);
    let v36 = b.konst(Width::new(8), 0x0);
    let v37 = b.cmp(CmpOp::Eq, v19, v36);
    let v39 = b.konst(Width::new(1), 0x1);
    let v40 = b.konst(Width::new(1), 0x0);
