    let v18 = b.konst(Width::new(1), 0x1);
    st.set(b, regs::FN, v18, None);
    let v19 = b.konst(Width::new(8), 0x7f);
    let v20 = b.cmp(CmpOp::Eq, v16, v19);
    let v22 = b.konst(Width::new(1), 0x1);
    let v23 = b.konst(Width::new(1), 0x0);
    let v24 = b.select(v20, v22, v23);
    st.set(b, regs::FP, v24, None);
    let v25 = b.extract(v16, 0, Width::new(4));
    let v26 = b.konst(Width::new(4), 0xf);
    let v27 = b.cmp(CmpOp::Eq, v25, v26);
    let v29 = b.konst(Width::new(1), 0x1);
    let v30 = b.konst(Width::new(1), 0x0);
    let v31 = b.select(v27, v29, v30);
    st.set(b, regs::FH, v31, None);
    let v32 = b.extract(v16, 7, Width::new(1));
    st.set(b, regs::FS, v32, None);
    let v33 = b.konst(Width::new(8), 0x0);
    let v34 = b.cmp(CmpOp::Eq, v16, v33);
    let v36 = b.konst(Width::new(1), 0x1);
    let v37 = b.konst(Width::new(1), 0x0);
    let v38 = b.select(v34, v36, v37);
    st.set(b, regs::FZ, v38, None);
    let v39 = b.extract(v16, 5, Width::new(1));
