/// `Op3F`.
///
/// Cut: Cycles, MemFetch, PAGE, STATE.
pub(super) fn Op3F(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Op3F;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let v1 = st.get(b, regs::Q);
    let v2 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::Q, v2, None);
    let v3 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::EIDELAY, v3, None);
    let v4 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::LDAIR, v4, None);
    st.fetched(st.pc(), 0, None);
    let v6 = st.get(b, regs::R);
    let v7 = b.extract(v6, 7, Width::new(1));
    let v8 = st.get(b, regs::R);
    let v9 = b.extract(v8, 0, Width::new(7));
    let v10 = b.konst(Width::new(7), 0x1);
    let v11 = b.bin(BinOp::Add, v9, v10);
    let v12 = b.concat(v7, v11);
    st.set(b, regs::R, v12, None);
    let v14 = b.not(v1);
    let v15 = st.get(b, regs::FY);
    let v16 = b.and(v15, v14);
    let v17 = st.get(b, regs::A);
    let v18 = b.extract(v17, 5, Width::new(1));
    let v19 = b.or(v16, v18);
    st.set(b, regs::FY, v19, None);
    let v20 = st.get(b, regs::FX);
    let v21 = b.and(v20, v14);
    let v22 = st.get(b, regs::A);
    let v23 = b.extract(v22, 3, Width::new(1));
    let v24 = b.or(v21, v23);
    st.set(b, regs::FX, v24, None);
    let v25 = st.get(b, regs::FC);
    let v26 = b.konst(Width::new(1), 0x1);
    st.set(b, regs::Q, v26, None);
    st.set(b, regs::FH, v25, None);
    let v27 = b.not(v25);
    st.set(b, regs::FC, v27, None);
    let v28 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FN, v28, None);
    st.cycles(b, 4, None);
    Ok(())
}

