/// Cut: Cycles, MemFetch, MemWrite, PAGE, STATE.
pub(super) fn Dd02(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Dd02;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let v1 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::Q, v1, None);
    let v2 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::EIDELAY, v2, None);
    let v3 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::LDAIR, v3, None);
    st.fetched(st.pc(), 0, None);
    let v5 = st.get(b, regs::R);
    let v6 = b.extract(v5, 7, Width::new(1));
    let v7 = st.get(b, regs::R);
    let v8 = b.extract(v7, 0, Width::new(7));
    let v9 = b.konst(Width::new(7), 0x1);
    let v10 = b.bin(BinOp::Add, v8, v9);
    let v11 = b.concat(v6, v10);
    st.set(b, regs::R, v11, None);
    let s12: u128 = st.pc().wrapping_add(0x1u128) & 0xffff;
    st.fetched(s12, 4, None);
    let v14 = st.get(b, regs::R);
    let v15 = b.extract(v14, 7, Width::new(1));
    let v16 = st.get(b, regs::R);
    let v17 = b.extract(v16, 0, Width::new(7));
    let v18 = b.konst(Width::new(7), 0x1);
    let v19 = b.bin(BinOp::Add, v17, v18);
    let v20 = b.concat(v15, v19);
    st.set(b, regs::R, v20, None);
    let v22 = st.get(b, regs::B);
    let v23 = st.get(b, regs::C);
    let v24 = b.concat(v22, v23);
    let v25 = st.get(b, regs::A);
    st.write(b, v24, v25, 8, None);
    let v26 = st.get(b, regs::A);
    let v27 = b.extract(v24, 0, Width::new(8));
    let v28 = b.konst(Width::new(8), 0x1);
    let v29 = b.bin(BinOp::Add, v27, v28);
    let v30 = b.concat(v26, v29);
    st.set(b, regs::WZ, v30, None);
    st.cycles(b, 11, None);
    Ok(())
}

