    let v23 = st.get(b, regs::IY);
    let v24 = b.konst(Width::new(16), 0x1);
    let v25 = b.bin(BinOp::Add, v22, v24);
    st.set(b, regs::WZ, v25, None);
    let v26 = b.zext(v22, Width::new(17));
    let v27 = b.zext(v23, Width::new(17));
    let v28 = b.bin(BinOp::Add, v26, v27);
    let v29 = b.extract(v28, 0, Width::new(16));
    st.set(b, regs::IY, v29, None);
    let v30 = b.konst(Width::new(1), 0x1);
    st.set(b, regs::Q, v30, None);
    let v31 = b.extract(v28, 16, Width::new(1));
    st.set(b, regs::FC, v31, None);
    let v32 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FN, v32, None);
    let v33 = b.bin(BinOp::Xor, v22, v23);
    let v34 = b.bin(BinOp::Xor, v33, v29);
    let v35 = b.extract(v34, 12, Width::new(1));
