    let v6 = b.extract(v5, 7, Width::new(1));
    let v7 = st.get(b, regs::R);
    let v8 = b.extract(v7, 0, Width::new(7));
    let v9 = b.konst(Width::new(7), 0x1);
    let v10 = b.bin(BinOp::Add, v8, v9);
    let v11 = b.concat(v6, v10);
    st.set(b, regs::R, v11, None);
    let s12: u128 = st.pc().wrapping_add(0x1u128) & 0xffff;
    st.fetched(s12, 4, None);
    let v14 = st.get(b, regs::R);
    let v15 = b.extract(v14, 7, Width::new(1));
    let v16 = st.get(b, regs::R);
    let v17 = b.extract(v16, 0, Width::new(7));
    let v18 = b.konst(Width::new(7), 0x1);
    let v19 = b.bin(BinOp::Add, v17, v18);
    let v20 = b.concat(v15, v19);
    st.set(b, regs::R, v20, None);
    let s21: u128 = st.pc().wrapping_add(0x2u128) & 0xffff;
    st.fetched(s21, 8, None);
    let s22: u128 = st.fetch(s21);
    let s23: u128 = s21.wrapping_add(0x1u128) & 0xffff;
    let v24 = st.get(b, regs::FC);
    let v25 = b.konst(Width::new(1), 0x0);
    let v26 = b.cmp(CmpOp::Eq, v24, v25);
    let s27: u128 = rt::sext(s22, 8, 16);
    let s28: u128 = s23.wrapping_add(s27) & 0xffff;
    let v29 = b.konst(Width::new(16), s28);
    st.set(b, regs::WZ, v29, Some(v26));
    st.branch(b, Target::Const((s28) as u16), Kind::Jump, Some(v26));
