    st.set(b, regs::FN, v37, None);
    let v38 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FH, v38, None);
    let v39 = b.extract(v34, 4, Width::new(4));
    let v40 = b.extract(v34, 0, Width::new(4));
    let v41 = b.bin(BinOp::Xor, v39, v40);
