    st.set(b, regs::R, v21, None);
    let s22: u128 = st.pc().wrapping_add(0x2u128) & 0xffff;
    st.fetched(s22, 8, None);
    let s23: u128 = st.fetch(s22);
    let s24: u128 = st.pc().wrapping_add(0x3u128) & 0xffff;
    st.fetched(s24, 11, None);
    let v26 = st.get(b, regs::IY);
    let s27: u128 = rt::sext(s23, 8, 16);
    let v28 = b.konst(Width::new(16), s27);
    let v29 = b.bin(BinOp::Add, v26, v28);
    st.set(b, regs::WZ, v29, None);
