    let v12 = b.cmp(CmpOp::Eq, v10, v11);
    let v13 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FP, v13, Some(v12));
    let v15 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::LDAIR, v15, None);
    let v16 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::EIDELAY, v16, None);
    let v17 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::Q, v17, None);
    let v18 = st.get(b, regs::SP);
    let v19 = b.konst(Width::new(16), 0x1);
    let v20 = b.bin(BinOp::Sub, v18, v19);
    let v21 = st.get(b, regs::SP);
    let v22 = b.konst(Width::new(16), 0x2);
    let v23 = b.bin(BinOp::Sub, v21, v22);
    let v24 = st.get(b, regs::I);
    let v25 = b.konst(Width::new(8), 0xff);
    let v26 = b.concat(v24, v25);
    let v27 = st.ret(b);
    let v28 = b.extract(v27, 8, Width::new(8));
