/// `LoneDD`.
///
/// Cut: Cycles, MemFetch, PAGE, STATE.
pub(super) fn LoneDD(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::LoneDD;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let v2 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::Q, v2, None);
    let v3 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::EIDELAY, v3, None);
    let v4 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::LDAIR, v4, None);
    st.fetched(st.pc(), 0, None);
    let v6 = st.get(b, regs::R);
    let v7 = b.extract(v6, 7, Width::new(1));
    let v8 = st.get(b, regs::R);
    let v9 = b.extract(v8, 0, Width::new(7));
    let v10 = b.konst(Width::new(7), 0x1);
    let v11 = b.bin(BinOp::Add, v9, v10);
    let v12 = b.concat(v7, v11);
    st.set(b, regs::R, v12, None);
    st.cycles(b, 4, None);
    Ok(())
}

